func check_prefix(ctx Context, tag string, x, y Value, res *Value) {
	if j := _project(ctx); j == nil { return } else
	{
		s := tag + ":" + j.spec
		k := rxLC.ReplaceAllString(sf("%v %v", ts(x), ts(y)), "=")
		t := sf("%v %s", *res, rxLC.ReplaceAllString(ts(*res), "="))
		v := check_prefix_specs[s][k]
		if t == v { return } else
		if v == nil {
			if false { debug(pc(pc(ctx,y),x),
				_f("`%v`:`%s`,", k, t),
				_f("note: \"%s\"", s),
				callstack{num:10}, trace{}) }
		} else {
			debug(pc(pc(ctx,y),x),
				_f("`%v`", k),
				_f(`got: %v`, t),
				_f(`!= : %v`, v),
				_f("note: \"%s\"", s),
				callstack{num:10}, trace{})
		}
	}
}

