func check(ctx Context, res Value, p Value, x ...Value) {
	var tx Value
	switch t := unloc(p).(type) {
	case *delegate: tx = t.x
	case *closure: tx = t.x
	}
	if rxIgnoredAutos.MatchString(tx.String()) { return }

	source := try[string](ctx,source{})
	src := strings.Split(source, ":")
	if src == nil { src = []string{""} }

	spec := func() (s string) { if j := _project(ctx); j != nil { s = j.spec }; return } ()

	d, _ := do(ctx, origin_def{}).(*def)

	k := func() (s string) {
		if false && 2 == len(src) && src[0] != "loader.go" { s = src[1] + " " }
		if false && d != nil { s += line_column(d)+":"+d.name+" " }
		s += p.String()+" "+ts(p)
		return
	} ()

	v := sf("%v %s", res, ts(res, ctx))

	t := func() any {
		switch t := checkspecs[spec][k].(type) {
		case sorted_list:
			if l, ok := res.(*list); ok {
				sort.Slice(l.elems, func(i, j int) bool {
					return l.elems[i].String() < l.elems[j].String()
				})
			}
			return []string(t)
		case map[string]any, map[string]string:
			debug(pc(pc(ctx,res),p), "%v %v", k, t)
			return nil
		default:
			return t
		}
	} ()

	switch _t := t.(type) {
	case []string: for _, s := range _t { if s == v { return } }
	case string: if _t == v { return }
	}

	debug(pc(pc(ctx,res),p), //_f("info: %v", _project(ctx)),
		_f("`%v`", k),
		_f(`got: %s`, v),
		_f(`!= : %v`, t),
		_f(`note: %v "%s"`, source, spec),
		callstack{num:8}, trace{})
}

