func check_cmp(ctx Context, l, r any, syn []bool) func(*cmpres) {
	k := rxLC.ReplaceAllString(sf("%v %v %v", ts(l), ts(r), syn), "=")
	return func(_res *cmpres) {
		if !truly(ctx, is_test_mode{}) { return }

		t := rxLC.ReplaceAllString(sf("%v", *_res), "=")
		if v := checkpoints_cmp[k]; v == "" {
			if true { prompt(ctx, "	`%v`:`%v`, //cmp: %v %v\n", k, t, l, r) } else
			{ debug(ctx, _f("`%v`:`%v`,", k, t), _f("%s, %v", ts(l), l), _f("%s, %v", ts(r), r), callstack{num:10}, trace{}) }
		} else if v != t {
			if false { prompt(ctx, "`%v`:`%v`, // %v %v\n", k, t, l, r) } else
			{ debug(ctx,
				_f("`%s`", k),
				_f("got: %s <- %v %v", t, l, r),
				_f("!= : %s", v),
				callstack{num:10}, trace{}) }
		}
	}
}

var checkpoints_com = map[string]map[string]any{
	".": map[string]any{
		"[] [{1:2:word test} {1:6:punct .} {1:7:word paniconexit0}]": "[test.paniconexit0] [{=compound {1:2:word test} {1:6:punct .} {1:7:word paniconexit0}}]",
		"[] [{1:21:word test} {1:25:punct .} {1:26:word timeout}]": "[test.timeout] [{=compound {1:21:word test} {1:25:punct .} {1:26:word timeout}}]",
	},
	"value": map[string]any{
		"[] [{13:11:word x} {13:13:word y}]": "[xy] [{=compound {13:11:word x} {13:13:word y}}]",
	},
}
func check_com(ctx *comctx, a, elems []Value, res *[]Value) {
	var (
		f = dirs(1, bases(_position(ctx).Filename, 2))
		k = sf("%v %v", ts(a), ts(elems))
		r = sf("%v %v", *res, ts(*res))
		t = checkpoints_com[f][k]
	)
	switch v := t.(type) {
	case   string: if r == v { return }
	case []string: for _, v := range v { if r == v { return } }
	default: if false { note(pc(ctx,elems), "%s: %v, %v => %v", f, k, t, r) }
	}
	if false { debug(pc(ctx,a), `"%v %v":"%v %v",`, a, elems, *res, trace{}) }
}

